using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed retrieval: returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person: {personInfo.Type.Name}");

// Round-trip via the typed info
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");
Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {p}");

// 2) Probe without throwing: TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {info!.Type.Name}");

// Now try a type that won't resolve (custom options with no resolver)
var empty = new JsonSerializerOptions { TypeInfoResolver = null };
if (!empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo(Person) on resolver-less options: not available (no exception!)");

record Person(string Name, int Age);

